import React from "react";
import "../App.css";

const Book = () => {
  const books = [
    {
      id: 1,
      img: ".../public/image1.jpg",
      bookName: "The Witch",
      Author: "Freida McFadden",
      price: "$48",
    },
    {
      id: 2,
      img: ".../public/image2.jpg",
      bookName: "The Answer Is No: A Short Story",
      Author: "Fredrik Backman",
      price: "$4",
    },
    {
      id: 3,
      img: ".../public/image3.jpg",
      bookName: "The Witch",
      Author: "Freida McFadden",
      price: "$48",
    },
  ];
  return <div></div>;
};

export default Book;
